def h(rows):
    return [Msg(w, t, datetime.fromisoformat(a)) for w, t, a in rows]


def test_term_named_yesterday_makes_order():
    reply = ("Здравствуйте! Да, в течение получаса оформим. 13 мес — 4 490 ₽ со скидкой за отзыв, оплата по ссылке СБП. "
             "Как будете у консоли — напишите, пришлю ссылку.")
    assert brain.REQ_PROMISE.search(reply)
    assert brain.promised_order(reply, h(SERGEI[:10]), PRICES) == {"product": "console", "months": 13, "price": 4590}


def test_after_consent_makes_order():
    reply = "Да, всё верно — 13 мес за 4 490 ₽. Ссылку на оплату пришлём в чат, оплатить можно с любого российского банка."
    assert brain.promised_order(reply, h(SERGEI[:16]), PRICES)["months"] == 13


def test_no_term_asks_term():
    reply = ("Оплата по ссылке СБП — пришлём её вместе с суммой, оплатить можно с любого российского банка. После оплаты "
             "подключаем удалённо: нужен код с экрана консоли, поэтому будьте рядом с ней.")
    assert brain.REQ_PROMISE.search(reply)
    assert brain.promised_order(reply, h(YURI), PRICES) == brain.TERM_WHICH


def test_term_from_old_purchase_not_used():
    old = datetime(2026, 11, 1, 12)
    rows = [Msg("client", "Давайте 6 месяцев", old), Msg("seller", "Вот реквизиты", old),
            Msg("client", "Здравствуйте, как оплатить?", old + timedelta(days=19))]
    assert brain.promised_order("Ссылку на оплату пришлю.", rows, PRICES) == brain.TERM_WHICH


def test_consent_to_seller_offer():
    now = datetime(2026, 11, 20, 12)
    rows = [Msg("client", "Хочу на 4 месяца", now), Msg("seller", "Оформим 6 мес на консоль — 2 290 ₽?", now),
            Msg("client", "давайте", now)]
    assert brain.promised_order("6 мес — 2 290 ₽, ссылку пришлю.", rows, PRICES)["months"] == 6


def test_platform_unclear_asks_platform():
    now = datetime(2026, 11, 20, 12)
    rows = [Msg("seller", "Прайс", now), Msg("client", "давайте 4 мес", now)]
    assert brain.promised_order("Ссылку пришлю.", rows, PRICES) == brain.PLATFORM_AGAIN
